            "rule": "a-batch-needs-every-test-case-confirmed",
            "contexts": [
              "batch"
            ],
            "statement": "A batch is refused as a whole, naming every unconfirmed test case, when any of its test cases lacks confirmed run permissions.",
            "via": [
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-batch-paused-for-thirty-days-stops",
            "contexts": [
              "batch"
            ],
            "statement": "A batch paused for 30 days stops with reason paused_too_long; one paused for less stays paused and can be resumed from its next unrun trial.",
            "via": [
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-batch-starts-no-trial-while-dispatch-is-paused",
            "contexts": [
              "batch"
            ],
            "statement": "While dispatch is paused for every provider, by an orphan threshold or a P1 incident, an evaluation batch waits instead of creating its next trial, and starts it on the first advance after the halt lifts.",
            "via": [
              "contracts/run-batch-trials-v1",
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-batch-whose-creator-is-gone-stops",
            "contexts": [
              "batch"
            ],
            "statement": "When a batch's creator no longer exists, the batch stops as creator_gone instead of starting another trial with no actor.",
            "via": [
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-batch-whose-test-case-is-gone-stops",
            "contexts": [
              "batch"
            ],
            "statement": "When starting a batch's next trial finds its target gone, the batch stops with reason target_gone and starts no further trial.",
            "via": [
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-refused-simulated-answer-pauses-the-batch",
            "contexts": [
              "batch"
            ],
            "statement": "When Run refuses a simulated person's answer because the owner's credit or run quota ran out, the batch pauses with that reason instead of closing the trial; a paused batch answers nothing, and resuming it gives the answers still owed.",
            "via": [
              "contracts/run-batch-trials-v1",
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "a-restored-account-is-purged-again-from-the-purge-record",
            "contexts": [
              "identity"
            ],
            "statement": "Replaying the purge record registers an erasure for, and purges at once, every recorded account the database holds alive; it leaves accounts already purged and accounts the database does not hold alone, and fails naming any record it cannot read or any account it could not purge.",
            "via": [
              "interactions/run-identity-workspace-purge"
            ]
          },
          {
            "rule": "account-purge-runs-every-owners-step-or-none",
            "contexts": [
              "identity"
            ],
            "statement": "Purging a deleted account runs the purge step of every Context that keeps data for its workspace (analytics, testlab, run, packaging, creation, eval, publishing, registry, ingest) together with the object listings of testlab, run and packaging; when any of them is missing, the purge refuses to start instead of purging part of the account.",
            "via": [
              "interactions/run-identity-workspace-purge"
            ]
          },
          {
            "rule": "an-account-purge-is-recorded-outside-the-database-first",
            "contexts": [
              "identity"
            ],
            "statement": "Once an account purge has claimed the account, it records the account in object storage, outside the database, before it removes any file or row; when that record cannot be written the purge stops and the account and its files stay as they were.",
            "via": [
              "interactions/run-identity-workspace-purge"
            ]
          },
          {
            "rule": "batch-waits-only-on-a-passing-refusal",
            "contexts": [
              "batch"
            ],
            "statement": "An evaluation batch waits when Run refuses a trial with a refusal Run says will pass on its own, including a run quota that could not be counted; pauses with the reason recorded when the refusal is one the owner can outwait or fix, a credit top-up or a used-up daily or windowed run quota; and stops with the reason recorded on any other refusal.",
            "via": [
              "contracts/run-batch-trials-v1",
              "interactions/run-batch-trials"
            ]
          },
          {
            "rule": "creation-reaches-its-collaborators-through-inversion",
            "contexts": [
              "creation"
            ],
            "statement": "Interactive Skill creation does not import the Contexts it collaborates with, and none of them imports it. Everything it needs from the reference, admission and trial Contexts arrives as a narrow interface injected by a composition root, so the creation loop can be replaced or removed without any other Context changing.",
            "via": [
              "interactions/run-activity-facts"
            ]
          },
          {
            "rule": "purge-removes-files-before-rows",
            "contexts": [
              "identity"
            ],
            "statement": "An account's stored files are removed before its database rows are erased, and the rows are erased in one transaction, so a failure leaves rows pointing at missing files that the next sweep can finish, never a file that no row names.",
            "via": [
              "interactions/run-identity-workspace-purge"
            ]
          },
          {
            "rule": "purge-waits-for-grace-and-quiet-workspace",
            "contexts": [
              "identity"
            ],
            "statement": "An account purge starts only when the deletion request is older than the 30-day grace at the moment of claiming and every Run in each of the Account's workspaces has finished cleanup; otherwise the purge is deferred (not failed) and retried by a later sweep.",
            "via": [
              "interactions/run-identity-workspace-purge"
            ]
          }
        ]
      }
    }
