            "summary": "A feedback kind must be blocking_issue or need_signal; any other or a missing kind is refused with 400."
          },
          {
            "id": "a-feedback-message-is-at-most-2000-characters",
            "status": "reviewed",
            "summary": "A feedback message is trimmed, must be non-blank and may hold at most 2000 characters; otherwise it is refused with 400."
          },
          {
            "id": "a-forged-analytics-session-cookie-is-replaced",
            "status": "reviewed",
            "summary": "An analytics session cookie that is not a minted id is never used as the session id; it is replaced with a fresh one."
          },
          {
            "id": "a-query-script-buckets-han-kana-and-hangul-together",
            "status": "reviewed",
            "summary": "A search query is recorded only by its script bucket, with Han, Hiragana, Katakana and Hangul all bucketed as han; the text itself is never stored."
          },
          {
            "id": "a-visit-cookie-always-lives-at-least-one-second",
            "status": "reviewed",
            "summary": "A visit cookie's lifetime never drops below one second, so in the last second before UTC midnight it still expires instead of becoming a browser-session cookie."
          },
          {
            "id": "a-visit-cookie-never-outlives-retention",
            "status": "reviewed",
            "summary": "The daily visit cookie lasts until UTC midnight but never longer than the analytics retention period."
          },
          {
            "id": "a-visit-starts-only-on-a-new-utc-date",
            "status": "reviewed",
            "summary": "A visit starts, and its cookie is reissued, only when the request has no visit cookie or one dated before today in UTC."
          },
          {
            "id": "an-account-purge-de-identifies-feedback",
            "status": "reviewed",
            "summary": "Purging an account detaches its funnel events from the Workspace and user, and erases its feedback reports' text, page and Run link, keeping only each report's kind and time for counting."
          },
          {
            "id": "analytics-events-past-retention-are-deleted-and-the-cutoff-row-kept",
            "status": "reviewed",
            "summary": "Maintenance deletes analytics events strictly older than the retention window; an event exactly at the cutoff is kept."
          },
          {
            "id": "analytics_events-arrival-check",
            "status": "candidate",

